def next_smallest_palindrome(n: int) -> int:
    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    def create_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    s = str(n)
    length = len(s)
    odd_length = (length % 2 != 0)

    # Edge case: if n < 9, next palindrome is n+1
    # (since single-digit palindromes are all digits)
    if n < 9:
        return n + 1

    # Split number into left half (including middle if odd length)
    mid = (length + 1) // 2
    left = s[:mid]

    # Construct palindrome from left half
    palindrome = create_palindrome(left, odd_length)
    if palindrome > n:
        return palindrome

    # If palindrome <= n, increment the left half and recreate palindrome
    left_num = int(left)
    left_num += 1
    left = str(left_num)

    # If length changed after increment (e.g., 999 -> 1000)
    if len(left) > mid:
        # This means the palindrome length increases by 1 or 2 digits,
        # e.g. 999 -> 1001 (next palindrome)
        # The smallest palindrome with length+1 digits is 10..01
        return int("1" + ("0" * (length - 1)) + "1")

    palindrome = create_palindrome(left, odd_length)
    return palindrome

def is_decimal(value: str) -> bool:
    if not isinstance(value, str):
        return False
    parts = value.split('.')
    if len(parts) != 2:
        return False
    integer_part, decimal_part = parts
    if not integer_part and not decimal_part:
        return False
    if not decimal_part.isdigit() or len(decimal_part) != 2:
        return False
    # Allow integer part to be empty (".12") or with sign ("-12.34")
    if integer_part.startswith(('+', '-')):
        integer_part = integer_part[1:]
    if integer_part and not integer_part.isdigit():
        return False
    return True

