import math

def min_Jumps(d: float, length: float) -> int:
    if d == 0:
        return 0
    if length == 0:
        return float('inf')  # Cannot move if step length is 0 and distance > 0

    if length >= d:
        return 1
    # If length < d, then at least 2 jumps are needed.
    # Because any single jump is length, and two jumps can be combined to reach any point within 2*length distance,
    # so if length < d <= 2*length, answer is 2.
    # But if d > 2*length, number of jumps is ceil(d/length).
    if d > 2 * length:
        return math.ceil(d / length)
    else:
        return 2

